    knownrebecs {
        Pong pong;
    }
    statevars {
        int count;
    }

    Ping() {
        count = 0;
        // equivalent of StartMessage
        self.start();
    }

    msgsrv start() {
        // println("Ping started the game!");
        pong.ping();
    }

